//! Concept help, with Rust-generated field facts and the actual program ABI on demand.
use anyhow::Result;
use std::io::Write;
use crate::{constants, help_text, root_help, topic_for_line};
/// Every scene and settings field, one line each; generated by scripts/generate-docs.
pub(crate) const REFERENCE: &str = include_str!("../../vork-scene/src/v2/reference.txt");

const PROGRAM_INPUTS: &str = include_str!(concat!(env!("OUT_DIR"),"/program-inputs.txt"));

fn document(topic: &str) -> Option<&'static str> {
    Some(match topic {
        "check" => include_str!("../../../docs/help/check.md"),
        "init" => include_str!("../../../docs/help/init.md"),
        "build" => include_str!("../../../docs/help/build.md"),
        "limits" => include_str!("../../../docs/help/limits.md"),
        "upgrade" => include_str!("../../../docs/help/upgrade.md"),
        "contract" => include_str!("../../../docs/help/contract.md"),
        "nodes" => include_str!("../../../docs/help/nodes.md"),
        "cameras" => include_str!("../../../docs/help/cameras.md"),
        "lights" => include_str!("../../../docs/help/lights.md"),
        "fog" => include_str!("../../../docs/help/fog.md"),
        "materials" => include_str!("../../../docs/help/materials.md"),
        "geometry" => include_str!("../../../docs/help/geometry.md"),
        "buffers" => include_str!("../../../docs/help/buffers.md"),
        "images" => include_str!("../../../docs/help/images.md"),
        "animation" => include_str!("../../../docs/help/animation.md"),
        "render" => include_str!("../../../docs/help/render.md"),
        "profiles" => include_str!("../../../docs/help/profiles.md"),
        "sdk" => include_str!("../../../docs/help/sdk.md"),
        "compositor" => include_str!("../../../docs/help/compositor.md"),
        "light-paths" => include_str!("../../../docs/help/light-paths.md"),
        "programs" => include_str!("../../../docs/help/programs.md"),
        "export" => include_str!("../../../docs/help/export.md"),
        "outputs" => include_str!("../../../docs/help/outputs.md"),
        "camera-json" => include_str!("../../../docs/help/camera-json.md"),
        "errors" => include_str!("../../../docs/help/errors.md"),
        "diagnostics" => include_str!("../../../docs/help/diagnostics.md"),
        _ => return None,
    })
}
/// The field's own line, or for an object path (e.g. `render`) every field beneath it.
fn field_lines(path: &str) -> Vec<&'static str> {
    let alias;
    let mut kind_alias = None;
    let path = if let Some((kind, tail)) = path.split_once('.') {
        if matches!(kind, "camera" | "mesh" | "light" | "asset") {
            kind_alias = Some(kind);
            alias = format!("node.{tail}");
            &alias
        } else { path }
    } else { path };
    let name = |line: &'static str| line.split_once(':').map(|(name, _)| name);
    REFERENCE.lines().chain(PROGRAM_INPUTS.lines()).filter(|line| {
        if let Some(kind) = kind_alias {
            if let Some((_, annotation)) = name(line).unwrap_or("").split_once(" (") {
                if annotation != format!("{kind})") { return false; }
            }
        }
        name(line).is_some_and(|name| name == path || {
            name.strip_prefix(path).is_some_and(|rest| rest.starts_with('.') || rest.starts_with(' '))
        })
    }).collect()
}
/// Diagnose only failed help lookups; scene decoding keeps its own suggestions.
fn unknown_field(path: &str) -> String {
    let library = path.split('/').next().filter(|name| vork_scene::libraries::library(name).is_some()).unwrap_or("std");
    let listing = format!("; list fields with `vork help {library} --all` or `vork help TOPIC --all`");
    // Variant annotations describe a field, but are not part of its wire path.
    fn wire_path(name: &str) -> &str { name.split_once(' ').map_or(name, |(path, _)| path) }
    fn leaf(name: &str) -> &str { wire_path(name).rsplit('.').next().unwrap_or(name) }
    fn area(name: &str) -> &str { name.split('.').next().unwrap_or(name) }
    let mut names: Vec<_> = REFERENCE.lines().chain(PROGRAM_INPUTS.lines())
        .filter_map(|line| line.split_once(':').map(|(name, _)| name))
        .filter(|name| name.contains('.')).collect();
    let distance = vork_scene::diagnostics::distance;
    names.sort_by_cached_key(|name| (
        distance(wire_path(path), wire_path(name)) + distance(leaf(path), leaf(name))
            + usize::from(area(path) != area(name)) * 2,
        *name,
    ));
    let matches: Vec<_> = names.iter().filter(|name| leaf(path) == leaf(name)).map(|name| {
        if let Some(setting) = wire_path(name).strip_prefix("settings.") {
            format!("{name} (profile setting; set with --set {setting}=...)")
        } else { (*name).to_owned() }
    }).take(5).collect();
    if !matches.is_empty() {
        return format!("unknown field {path:?}; use {}", matches.join(", ")) + &listing;
    }
    let shown = names.iter().take(5).copied().collect::<Vec<_>>().join(", ");
    format!("unknown field {path:?}; did you mean {:?}? Nearest valid names ({} of {}): {shown}",
        names[0], names.len().min(5), names.len()) + &listing
}
/// Root fields and lookup-only contracts remain addressable without topic duplication.
fn topic_lines(topic: &str) -> impl Iterator<Item = &'static str> + '_ {
    REFERENCE.lines().filter(move |line|
        topic_for_line(line) == Some(topic) && !vork_scene::v2::api_field(line)
            && !vork_scene::v2::lookup_only_field(line))
}
pub fn run(topic: Option<&str>, field: Option<&str>, all: bool) -> Result<()> {
    let words: Vec<_> = topic.unwrap_or_default().split_whitespace().collect();
    let all = all || words.contains(&"--all");
    let words: Vec<_> = words.into_iter().filter(|word| *word != "--all").collect();
    let (topic, field) = match words.as_slice() {
        [] => (None, field),
        [topic] => (Some(*topic), field),
        [topic, path] if field.is_none() => (Some(*topic), Some(*path)),
        _ => return Err(usage("`vork help` takes TOPIC [PATH] [--all]")),
    };
    serve(topic, field, all)?;
    std::io::stdout().flush().map_err(crate::output::error)
}
fn usage(message: impl std::fmt::Display) -> anyhow::Error {
    anyhow::anyhow!("{message}").context(vork_render::failure::FailureKind::Usage)
}
fn serve(topic: Option<&str>, field: Option<&str>, all: bool) -> Result<()> {
    if field.is_some() && topic != Some("field") { return Err(usage("extra argument requires `vork help field PATH`")); }
    let topic = match topic {
        Some(program @ ("std/hair" | "std/sky" | "std/text")) => return serve(Some("field"), Some(program), true),
        Some("std/camera") => return serve(Some("cameras"), None, true),
        topic => topic,
    };
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let Some(topic) = topic else { write!(out, "{}", root_help()).map_err(crate::output::error)?; return Ok(()); };
    if topic == "field" {
        let path = field.ok_or_else(|| usage("use `vork help field PATH`, e.g. node.target"))?;
        let lines = field_lines(path);
        if lines.is_empty() { return Err(usage(unknown_field(path))); }
        for line in lines { writeln!(out, "{line}").map_err(crate::output::error)?; }
        return Ok(());
    }
    if let Some(library) = vork_scene::libraries::library(topic) {
        let (summary, details) = library.help.split_once("<!-- all -->").unwrap_or((library.help, ""));
        write!(out, "{}", help_text(summary)).map_err(crate::output::error)?;
        if all {
            write!(out, "{}", help_text(details)).map_err(crate::output::error)?;
            for line in topic_lines(topic) { writeln!(out, "{line}").map_err(crate::output::error)?; }
            for line in PROGRAM_INPUTS.lines().filter(|line| line.starts_with(&format!("{topic}/"))) {
                writeln!(out, "{line}").map_err(crate::output::error)?;
            }
            if topic == "std" { write!(out, "{}", help_text(crate::std_command::HELP)).map_err(crate::output::error)?; }
        }
        return Ok(());
    }
    let Some(text) = document(topic) else {
        let error = vork_scene::diagnostics::unknown("help topic", topic, constants::HELP_TOPICS.iter().copied());
        return Err(usage(format!("{error}; use `vork help` for the topic list")));
    };
    // A page's `<!-- all -->` line ends its default part; the rest prints with --all.
    let (summary, details) = text.split_once("<!-- all -->").unwrap_or((text, ""));
    write!(out, "{}", help_text(summary)).map_err(crate::output::error)?;
    if topic == "cameras" { for line in field_lines("std/camera") { writeln!(out, "{line}").map_err(crate::output::error)?; } }
    if all {
        write!(out, "{}", help_text(details)).map_err(crate::output::error)?;
        for line in topic_lines(topic) { writeln!(out, "{line}").map_err(crate::output::error)?; }
        if topic == "programs" { writeln!(out, "\n```slang\n{}```", vork_render::program_help()).map_err(crate::output::error)?; }
    }
    Ok(())
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn resource_binding_fields_show_authorable_map_values() {
        for path in ["program.bindings", "mesh.instances.attributes"] {
            let lines = field_lines(path);
            assert_eq!(lines.len(), 1);
            assert!(lines[0].contains("JSON shape: {name: string|Buffer object}"), "{}", lines[0]);
        }
        assert!(topic_lines("programs").any(|line| line.starts_with("program.bindings:") && line.contains("JSON shape:")));
        assert!(topic_lines("nodes").any(|line| line.starts_with("node.instances.attributes (mesh):") && line.contains("JSON shape:")));
    }

    #[test]
    fn camera_fields_and_heading_paths_resolve() {
        for name in ["lens", "sensor_width", "shift", "use_dof", "aperture_blades", "projection"] {
            assert_eq!(field_lines(&format!("std/camera.{name}")).len(), 1);
        }
        assert!(field_lines("camera.material")[0].contains("(camera)"));
        assert!(field_lines("camera.energy").is_empty());
        assert!(!field_lines("mesh.geometry").is_empty());
    }
    #[test]
    fn program_recovery_prefers_real_fields() {
        for leaf in ["emission_luminance", "subsurface_radius_scale"] {
            let lines = field_lines(&format!("std/openpbr.{leaf}"));
            assert_eq!(lines.len(), 1);
        }
        assert!(unknown_field("std/hair.not_a_field").contains("vork help std"));
        assert!(unknown_field("std/sky.not_a_field").contains("vork help std"));
        assert!(unknown_field("node.targ").contains("node.target"));
    }
    #[test]
    fn bundled_inputs_include_defaults_tokens_and_declared_ranges() {
        let hair = field_lines("std/hair");
        assert_eq!(hair.len(), 14);
        assert!(field_lines("std/hair.parametrization")[0].contains("color|melanin|absorption"));
        assert!(field_lines("std/hair.color")[0].contains("default [0.017513,0.005763,0.002059]"));
        assert!(field_lines("std/hair.roughness")[0].contains("default 0.3; no declared range"));
        assert_eq!(field_lines("std/sky").len(), 6);
        assert!(field_lines("std/sky.altitude")[0].contains("default 100; range [0,100000]"));
        assert!(field_lines("std/text.size")[0].contains("default 1; metres per font em"));
        assert!(field_lines("std/text.align_y")[0].contains("default top_baseline"));
        let upgrade = document("upgrade").unwrap();
        assert!(!upgrade.contains("lane x"));
        assert!(upgrade.contains("material.priority"));
        assert!(field_lines("material.priority")[0].contains("default 0"));
        assert!(!upgrade.contains("Fog returns"));
    }
    #[test]
    fn target_help_explains_structural_aim_animation() {
        assert!(field_lines("node.target")[0].contains("structural, not animatable"));
        let animation = document("animation").unwrap();
        assert!(animation.contains("including [x,y,z]"));
        assert!(animation.contains("evaluated translation track"));
    }
    #[test]
    fn png_alpha_is_documented() {
        let outputs = document("outputs").unwrap();
        assert!(outputs.contains(".png RGBA still (keeps alpha"));
        assert!(outputs.contains("render.background \"transparent\""));
    }
    #[test]
    fn every_supported_openpbr_input_has_exact_help() {
        use vork_scene::v2::{OpenPbrParam, OPENPBR};
        for p in OPENPBR {
            let path = format!("material.inputs.{}", p.name);
            let lines = field_lines(&path);
            assert_eq!(lines.len(), usize::from(p.supported), "{path}");
            assert_eq!(vork_scene::v2::validate_openpbr_input(p.name).is_ok(), p.supported);
            if p.supported {
                assert!(!topic_lines("materials").any(|line| line == lines[0]), "{path}");
                assert!(lines[0].contains(&format!("default {}", p.default_text)), "{}", lines[0]);
                if matches!(p.kind, vork_scene::v2::OpenPbrKind::Float | vork_scene::v2::OpenPbrKind::Color3) {
                    let range = format!("range {}{},{}{}",
                        if p.open_min { '(' } else { '[' }, p.min, p.max,
                        if p.open_max { ')' } else { ']' });
                    let suffix = if p.kind == vork_scene::v2::OpenPbrKind::Color3 { " per channel" } else { "" };
                    assert!(lines[0].contains(&format!("{range}{suffix};")), "{}", lines[0]);
                    assert_eq!(lines[0].contains("per channel"), p.kind == vork_scene::v2::OpenPbrKind::Color3, "{}", lines[0]);
                }
                let unit = match p.unit { "" => "dimensionless", "length" => "metres", unit => unit };
                assert!(lines[0].contains(&format!("units {unit};")), "{}", lines[0]);
                assert!(field_lines(&path[..path.len()-1]).is_empty(), "{path}");
            }
        }
        let root = field_lines("material.inputs (std/openpbr)");
        let names = root[0].split("shaded inputs: ").nth(1).unwrap().split_whitespace().collect::<Vec<_>>();
        assert_eq!(names, OpenPbrParam::supported().map(|p| p.name).collect::<Vec<_>>());
    }
    #[test]
    fn fields_cover_both_tiers_and_do_not_match_prefixes() {
        assert!(field_lines("node.target")[0].contains("aims -Z"));
        assert!(field_lines("settings.denoise")[0].contains("bool"));
        assert!(field_lines("settings.fast_gi.method").is_empty());
        assert!(field_lines("node.targ").is_empty());
        let render = field_lines("render");
        assert!(render.iter().any(|line| line.starts_with("render.fps:")), "{render:?}");
        assert!(render.iter().all(|line| line.starts_with("render.") || line.starts_with("render ")), "{render:?}");
        let blur = field_lines("render.motion_blur");
        assert!(blur.iter().any(|line| line.starts_with("render.motion_blur:")), "{blur:?}");
        assert!(blur.iter().any(|line| line.starts_with("render.motion_blur.")), "{blur:?}");
    }
    #[test]
    fn root_fields_move_out_of_topics_but_remain_addressable() {
        let root = root_help();
        for (path, spelling) in [
            ("node.material", "omitted = std/camera; optics are program inputs"),
            ("node.geometry", "geometry: geometry-name|inline geometry"),
            ("render.fps", "fps: number|rational string = 24"),
            ("material.texture.image", "image: image-name|inline image"),
        ] {
            assert!(root.contains(spelling), "{path}");
            for line in field_lines(path) {
                assert!(vork_scene::v2::api_field(line), "{line}");
                assert!(!topic_lines(topic_for_line(line).unwrap()).any(|l| l == line), "{line}");
            }
        }
        for path in ["node.skin", "geometry.morphs", "animation.clip", "image.render", "program.bindings", "settings.seed"] {
            let lines = field_lines(path);
            assert!(!lines.is_empty(), "{path}");
            for line in lines {
                assert!(topic_lines(topic_for_line(line).unwrap()).any(|l| l == line), "{line}");
            }
        }
    }
    #[test]
    fn every_public_topic_has_a_source() {
        for topic in constants::HELP_TOPICS.iter() {
            assert!(*topic == "field" || document(topic).is_some() || vork_scene::libraries::library(topic).is_some(), "{topic}");
        }
    }
}
